CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS hardware_profiles(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,os TEXT,cpu TEXT,ram_bytes INTEGER);CREATE TABLE IF NOT EXISTS gpus(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,model TEXT,vram_bytes INTEGER,driver TEXT,FOREIGN KEY(profile_id) REFERENCES hardware_profiles(id));CREATE TABLE IF NOT EXISTS models(id TEXT PRIMARY KEY,provider TEXT NOT NULL,repository TEXT NOT NULL,name TEXT NOT NULL,architecture TEXT,parameter_count INTEGER,context_length INTEGER,task TEXT,license TEXT,downloads INTEGER,likes INTEGER,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS model_variants(id TEXT PRIMARY KEY,model_id TEXT NOT NULL,format TEXT NOT NULL,quantization TEXT,file_size INTEGER,estimated_ram INTEGER,estimated_vram INTEGER,runtime_hint TEXT,FOREIGN KEY(model_id) REFERENCES models(id));CREATE TABLE IF NOT EXISTS runtimes(id TEXT PRIMARY KEY,name TEXT NOT NULL,version TEXT,status TEXT NOT NULL,install_path TEXT);CREATE TABLE IF NOT EXISTS downloads(id TEXT PRIMARY KEY,model_variant_id TEXT NOT NULL,url TEXT NOT NULL,destination TEXT NOT NULL,status TEXT NOT NULL,bytes_total INTEGER,bytes_done INTEGER,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS installed_models(id TEXT PRIMARY KEY,variant_id TEXT NOT NULL,path TEXT NOT NULL,status TEXT NOT NULL,installed_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS model_benchmarks(id TEXT PRIMARY KEY,model_id TEXT NOT NULL,tokens_per_second REAL,prompt_tokens_per_second REAL,peak_ram_bytes INTEGER,peak_vram_bytes INTEGER,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS chat_sessions(id TEXT PRIMARY KEY,model_id TEXT,title TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS chat_messages(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS api_servers(id TEXT PRIMARY KEY,host TEXT NOT NULL,port INTEGER NOT NULL,status TEXT NOT NULL,api_key_enabled INTEGER NOT NULL DEFAULT 0);